import { useState } from "react";
import { useProduits } from "../hooks/useProduits";
import ListeProduits from "../components/catalogue/ListeProduits";
import BarreRecherche from "../components/catalogue/BarreRecherche";
import FiltreCategorie from "../components/catalogue/FiltreCategorie";

export default function Catalogue() {
  const { produits, categories, chargement } = useProduits();
  const [recherche, setRecherche] = useState("");
  const [categorie, setCategorie] = useState("");

  const produitsFiltres = produits.filter((p) => {
    const matchRecherche = p.title.toLowerCase().includes(recherche.toLowerCase());
    const matchCategorie = categorie ? p.category === categorie : true;
    return matchRecherche && matchCategorie;
  });

  if (chargement) return <p style={{ textAlign: "center", padding: "40px" }}>Chargement...</p>;

  return (
    <div style={{ padding: "30px" }}>
      <h2 style={{ marginBottom: "20px" }}>Catalogue</h2>
      <BarreRecherche valeur={recherche} onChange={setRecherche} />
      <FiltreCategorie categories={categories} actif={categorie} onChange={setCategorie} />
      <ListeProduits produits={produitsFiltres} />
    </div>
  );
}
